func SumPerLine(b []byte) (ret int64) {
	var wg sync.WaitGroup
	var last int
	for i := 0; i < len(b); i++ {
		if b[i] != '\n' {
			continue
		}
		wg.Add(1)
		go func(line []byte) {
			defer wg.Done()
			num, err := ParseInt(line)
			if err != nil {
				return
			}
			ret += num
		}(b[last:i])
		last = i + 1
	}
	wg.Wait()
	return ret
}
